def peak_sample(samples, width):
    if type(width) is not int or width <= 0 or any(type(x) is not int for x in samples):
        raise ValueError("invalid input")
    if width > len(samples):
        return None
    total = sum(samples[:width])
    best = total
    index = 0
    for right in range(width, len(samples)):
        total += samples[right] - samples[right - width]
        if total > best:
            best = total
            index = right - width + 1
    return index

def allocate_quota(weights, total):
    if not weights or any(type(w) is not int or w <= 0 for w in weights) or type(total) is not int or total < 0:
        raise ValueError("invalid quota inputs")
    base = sum(weights)
    shares = [divmod(total * w, base) for w in weights]
    result = [part for part, _ in shares]
    order = sorted(range(len(weights)), key=lambda i: (-shares[i][1], i))
    for i in order[:total - sum(result)]:
        result[i] += 1
    return result

def audit_gaps(events):
    by_stream = {}
    for stream, sequence in events:
        if not isinstance(stream, str) or not stream or type(sequence) is not int or sequence <= 0:
            raise ValueError("invalid event")
        by_stream.setdefault(stream, set()).add(sequence)
    result = {}
    for stream, values in by_stream.items():
        ordered = sorted(values)
        gaps = [(left + 1, right - 1) for left, right in zip(ordered, ordered[1:]) if right > left + 1]
        if gaps:
            result[stream] = gaps
    return result
